9	// IsHumanIdentity reports whether an actor or verifier identifier denotes a human:
10	// "human" alone or followed by ':' or '/', compared case-insensitively.
11	// It is the single definition used by the provenance guard and by the verified.by filter.
12	func IsHumanIdentity(id string) bool {
13		lower := strings.ToLower(strings.TrimSpace(id))
14		if lower == "human" {
15			return true
16		}
17		return strings.HasPrefix(lower, "human:") || strings.HasPrefix(lower, "human/")
18	}
19	
20	// ensureNoForgedHumanVerification rejects human verifications that a non-human actor adds to c.
21	// Verifications already recorded for the concept at fullPath may be preserved. A new concept
22	// inherits nothing from a file that already exists at its path.
23	//
24	// The actor is self-declared, so this guards callers that cannot choose it (the MCP server)
25	// and accidental or injected forgery; it does not authenticate a CLI user who passes --actor.
26	func ensureNoForgedHumanVerification(fullPath string, c *Concept, actor string, isNew bool) error {
27		if IsHumanIdentity(actor) {
28			return nil
29		}
30		var recorded map[Verified]bool
31		if !isNew {
32			recorded = recordedVerifications(fullPath)
33		}
34		for _, v := range c.Verified {
35			if IsHumanIdentity(v.By) && !recorded[v] {
36				return fmt.Errorf("actor %q cannot add human verification %q", actor, v.By)
37			}
38		}
39		return nil
40	}
41	
42	// recordedVerifications returns the verifications stored in the concept file at fullPath.
43	func recordedVerifications(fullPath string) map[Verified]bool {
44		// #nosec G304 -- fullPath is resolved and confined to the bundle by resolveInBundle
45		data, err := os.ReadFile(fullPath)
46		if err != nil {
47			return nil
48		}
49		existing, err := ParseConcept("", string(data))
50		if err != nil {
51			return nil
52		}
53		recorded := make(map[Verified]bool, len(existing.Verified))
54		for _, v := range existing.Verified {
55			recorded[v] = true
56		}
57		return recorded
58	}
